WITH with_windows AS (SELECT *, MAX(budget) OVER w_grp AS dept_name_max_budget, ROW_NUMBER() OVER (PARTITION BY location, dept_name ORDER BY budget DESC, id) AS seq_no, DENSE_RANK() OVER w_recent AS budget_dense_rank, NTILE(10) OVER (PARTITION BY dept_name, location ORDER BY budget, id) AS budget_bucket, SUM(budget) OVER (PARTITION BY location, dept_name ORDER BY budget, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_budget FROM departments WINDOW w_grp AS (PARTITION BY dept_name), w_recent AS (PARTITION BY location ORDER BY budget)) SELECT CASE WHEN budget_bucket >= 7 THEN 'HIGH' ELSE 'LOW' END AS budget_bucket_tier, CASE WHEN budget_dense_rank >= 8 THEN 'LARGE' ELSE 'SMALL' END AS budget_dense_rank_tier, CASE WHEN running_budget >= 19088276 THEN 'HIGH' ELSE 'LOW' END AS running_budget_tier, COUNT(CASE WHEN location = 'Singapore' THEN 1 END) AS singapore_count, MIN(dept_name_max_budget) AS min_dept_name_max_budget, PERCENTILE_APPROX(seq_no, ARRAY(0.25, 0.5, 0.75)) AS seq_no_quartiles, SUM(CASE WHEN dept_name = 'HR' THEN budget_bucket ELSE 0 END) AS hr_budget_bucket FROM with_windows GROUP BY CASE WHEN budget_bucket >= 7 THEN 'HIGH' ELSE 'LOW' END, CASE WHEN budget_dense_rank >= 8 THEN 'LARGE' ELSE 'SMALL' END, CASE WHEN running_budget >= 19088276 THEN 'HIGH' ELSE 'LOW' END ORDER BY hr_budget_bucket DESC
